-- Migration: Year 3 - Psychiatry - Personality Disorders MCQ Bank (1-320)
-- Based on Kaplan & Sadock's Synopsis 12th Ed, First Aid for the Psychiatry Clerkship 5th Ed, and MGH Pocket Psychiatry
-- Date: 2026-04-30

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'personality-disorders' LIMIT 1;

    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: General Personality Concepts & Cluster A (1-80)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What defines a Personality Disorder according to DSM-5?', '["A temporary reaction to stress", "An enduring pattern of inner experience and behavior that deviates markedly from cultural expectations, is pervasive and inflexible, and causes impairment", "A medical condition", "None"]', 1, 'Must have onset in adolescence or early adulthood. (DSM-5)'),
    (v_topic_id, '2: How many clusters of Personality Disorders exist in the DSM-5?', '["2", "3 (Clusters A, B, and C)", "4", "5"]', 1, 'Categorized based on descriptive similarities. (First Aid)'),
    (v_topic_id, '3: Which personality disorders make up Cluster A (the ''''weird'''' or ''''eccentric'''' cluster)?', '["Borderline, Antisocial, Narcissistic", "Paranoid, Schizoid, Schizotypal", "Avoidant, Dependent, OCPD", "None"]', 1, 'Characterized by odd, eccentric thinking or behavior. (MGH Pocket)'),
    (v_topic_id, '4: Which personality disorders make up Cluster B (the ''''wild'''' or ''''dramatic'''' cluster)?', '["Paranoid, Schizoid", "Antisocial, Borderline, Histrionic, Narcissistic", "Avoidant, Dependent", "None"]', 1, 'Characterized by dramatic, overly emotional, or unpredictable thinking/behavior. (Kaplan & Sadock)'),
    (v_topic_id, '5: Which personality disorders make up Cluster C (the ''''worried'''' or ''''anxious'''' cluster)?', '["Schizotypal, Paranoid", "Avoidant, Dependent, Obsessive-Compulsive", "Borderline, Histrionic", "None"]', 1, 'Characterized by anxious, fearful thinking or behavior. (First Aid)'),
    (v_topic_id, '6: Are Personality Disorders considered egosyntonic or egodystonic?', '["Egodystonic", "Egosyntonic (patients do not believe they have a problem and think their behavior is normal)", "Neither", "None"]', 1, 'This makes them notoriously difficult to treat because patients rarely seek help on their own. (MGH Pocket)'),
    (v_topic_id, '7: Can a personality disorder be formally diagnosed in a patient under 18 years old?', '["Never", "Yes, in rare cases if features have been present for at least 1 year (EXCEPT Antisocial Personality Disorder, which absolutely requires age 18+)", "Always", "None"]', 1, 'ASPD cannot be diagnosed before 18; Conduct Disorder is the precursor. (Kaplan & Sadock)'),
    (v_topic_id, '8: What is the genetic relationship between Cluster A personality disorders and psychotic disorders?', '["None", "Higher rates of Cluster A disorders are found in biological relatives of patients with Schizophrenia", "Protective factor", "None"]', 1, 'Schizotypal in particular has strong familial links to Schizophrenia. (First Aid)'),
    (v_topic_id, '9: What defense mechanism is classically utilized by patients with Paranoid Personality Disorder?', '["Repression", "Projection (attributing their own unacceptable feelings/thoughts onto others)", "Sublimation", "None"]', 1, '"I''m not angry, YOU are angry!" (MGH Pocket)'),
    (v_topic_id, '10: What defense mechanism is classically utilized by patients with Schizoid Personality Disorder?', '["Acting out", "Fantasy (retreating into an imaginary inner life to avoid external intimacy)", "Reaction formation", "None"]', 1, 'Provides an escape from human interaction. (Kaplan & Sadock)'),
    (v_topic_id, '11: What is the defining feature of Paranoid Personality Disorder (PPD)?', '["Visual hallucinations", "A pervasive distrust and suspiciousness of others such that their motives are interpreted as malevolent", "Fear of spiders", "None"]', 1, 'Begins by early adulthood and is present in a variety of contexts. (DSM-5)'),
    (v_topic_id, '12: A patient with Paranoid Personality Disorder believes her spouse is cheating on her. How does this differ from Delusional Disorder (Jealous type)?', '["It is the same", "In PPD, the suspicion is pervasive but NOT fixed/bizarre enough to be a true delusion; they can sometimes entertain alternative explanations", "None", "None"]', 1, 'Delusions are fixed, false beliefs impervious to logic. (First Aid)'),
    (v_topic_id, '13: How do patients with Paranoid Personality Disorder typically respond to perceived insults?', '["They ignore them", "They are quick to react with anger and often counterattack, bearing long-lasting grudges", "They cry", "None"]', 1, 'They are extremely sensitive to slights. (MGH Pocket)'),
    (v_topic_id, '14: Which of the following is NOT a DSM-5 criterion for Paranoid Personality Disorder?', '["Reluctance to confide in others", "Reads hidden demeaning meanings into benign remarks", "Auditory hallucinations commanding violence", "Recurrent suspicions regarding fidelity of spouse"]', 2, 'PPD does NOT include true psychotic hallucinations or delusions. (Kaplan & Sadock)'),
    (v_topic_id, '15: A patient refuses to sign a surgical consent form, stating, ''''The hospital is just trying to steal my organs to sell them on the black market, just like they do to everyone else.'''' Diagnosis?', '["Schizoid PD", "Paranoid Personality Disorder (if this reflects a lifelong pattern of distrust)", "Histrionic PD", "None"]', 1, 'Extreme suspiciousness without full-blown psychosis. (First Aid)'),
    (v_topic_id, '16: What is the most appropriate approach when interviewing a patient with Paranoid Personality Disorder?', '["Use humor", "Maintain a formal, respectful, and honest stance. Avoid being overly warm, which they may view as suspicious.", "Argue with them", "None"]', 1, 'Clear boundaries and transparency build trust. (MGH Pocket)'),
    (v_topic_id, '17: Pharmacological treatment for Paranoid Personality Disorder?', '["First-line is Lithium", "Rarely indicated; low-dose antipsychotics or anxiolytics may be used transiently for severe agitation/paranoia", "Stimulants", "None"]', 1, 'Psychotherapy is the mainstay, though engagement is difficult. (Kaplan & Sadock)'),
    (v_topic_id, '18: What is the defining feature of Schizoid Personality Disorder?', '["Attention-seeking", "A pervasive pattern of detachment from social relationships and a restricted range of emotional expression", "Severe paranoia", "None"]', 1, 'They prefer to be alone and do not desire intimacy. (DSM-5)'),
    (v_topic_id, '19: A 25-year-old man works the night shift as a toll booth operator. He has no friends, shows no interest in sexual relationships, and appears indifferent to praise or criticism. Diagnosis?', '["Avoidant PD", "Schizoid Personality Disorder", "Social Anxiety Disorder", "None"]', 1, 'Classic presentation of Schizoid PD (content with isolation). (First Aid)'),
    (v_topic_id, '20: How does Schizoid Personality Disorder differ from Avoidant Personality Disorder?', '["They are the same", "Schizoid patients DESIRE isolation (they don''t want friends). Avoidant patients desire friends but avoid them due to intense FEAR of rejection.", "None", "None"]', 1, 'Crucial distinction for board exams. (MGH Pocket)'),
    (v_topic_id, '21: Which of the following is a classic trait of Schizoid Personality Disorder?', '["Always wears bright colors", "Almost always chooses solitary activities and lacks close friends other than first-degree relatives", "Hypersexuality", "None"]', 1, 'They are the "loners" of the psychiatric world. (Kaplan & Sadock)'),
    (v_topic_id, '22: Do patients with Schizoid Personality Disorder experience loneliness?', '["Always", "Rarely; they genuinely prefer isolation and find social interaction unrewarding", "Only at night", "None"]', 1, 'They lack the fundamental drive to connect. (First Aid)'),
    (v_topic_id, '23: What is the typical affect of a patient with Schizoid Personality Disorder?', '["Labile", "Emotionally cold, detached, or flattened affect", "Overly dramatic", "None"]', 1, 'They rarely experience strong emotions, either positive or negative. (MGH Pocket)'),
    (v_topic_id, '24: A key differential diagnosis for Schizoid Personality Disorder is Autism Spectrum Disorder (ASD). How do they differ?', '["ASD has more friends", "ASD typically presents in early childhood with prominent repetitive behaviors and severe communication deficits; Schizoid PD lacks repetitive behaviors and presents later", "None", "None"]', 1, 'ASD is a neurodevelopmental disorder. (Kaplan & Sadock)'),
    (v_topic_id, '25: Best therapeutic approach for Schizoid Personality Disorder?', '["Force group therapy", "Respect their need for distance; individual therapy focusing on practical coping skills, but they rarely seek treatment", "High dose SSRIs", "None"]', 1, 'Do not force socialization, it will drive them away. (First Aid)'),
    (v_topic_id, '26: What is the defining feature of Schizotypal Personality Disorder?', '["Social withdrawal only", "A pervasive pattern of social/interpersonal deficits, cognitive or perceptual distortions, and ECCENTRIC behavior", "Panic attacks", "None"]', 1, 'The "magical thinking" disorder. (DSM-5)'),
    (v_topic_id, '27: A 30-year-old woman wears odd, mismatched clothing, believes she can predict the weather using her crystals, and feels extreme discomfort in social situations because she feels she doesn''t "fit in." Diagnosis?', '["Histrionic PD", "Schizotypal Personality Disorder", "Bipolar Disorder", "None"]', 1, 'Classic eccentricities and magical thinking without frank psychosis. (MGH Pocket)'),
    (v_topic_id, '28: What is "Magical Thinking" as seen in Schizotypal PD?', '["Doing card tricks", "Belief that one''s thoughts, words, or actions can influence events in the external world (e.g., telepathy, sixth sense)", "None", "None"]', 1, 'Normal in children, pathological in adults. (Kaplan & Sadock)'),
    (v_topic_id, '29: Do patients with Schizotypal Personality Disorder have social anxiety?', '["No", "Yes, prominent social anxiety that tends to be associated with paranoid fears rather than negative judgments about self", "None", "None"]', 1, 'Unlike Avoidant PD, their anxiety does not diminish with familiarity. (First Aid)'),
    (v_topic_id, '30: How does Schizotypal Personality Disorder differ from Schizophrenia?', '["It is the same", "Schizotypal patients do NOT have frank, sustained delusions or hallucinations. They have ''''illusions'''' or ''''odd beliefs.''''", "None", "None"]', 1, 'Schizotypal patients remain grounded in reality, though barely. (MGH Pocket)'),
    (v_topic_id, '31: Which of the following is a criterion for Schizotypal PD?', '["Ideas of reference (excluding delusions of reference)", "Command hallucinations", "Severe mania", "None"]', 1, 'An event having special, personal meaning to the patient (e.g., the TV newscaster is blinking specifically at them). (Kaplan & Sadock)'),
    (v_topic_id, '32: What type of speech is common in Schizotypal Personality Disorder?', '["Word salad", "Odd thinking and speech (e.g., vague, circumstantial, metaphorical, overelaborate, or stereotyped)", "Mute", "None"]', 1, 'Speech is odd but generally coherent enough to follow. (First Aid)'),
    (v_topic_id, '33: Is brief psychotic reactivity possible in Schizotypal Personality Disorder?', '["Never", "Yes, transient psychotic episodes (minutes to hours) can occur under severe stress", "Always", "None"]', 1, 'Also known as micropsychotic episodes. (MGH Pocket)'),
    (v_topic_id, '34: What percentage of patients with Schizotypal PD eventually progress to full-blown Schizophrenia?', '["100%", "Approximately 10%", "0%", "None"]', 1, 'Considered by many to be part of the schizophrenia spectrum. (Kaplan & Sadock)'),
    (v_topic_id, '35: Pharmacological treatment for Schizotypal Personality Disorder?', '["Lithium", "Low-dose atypical antipsychotics (e.g., Risperidone, Aripiprazole) can significantly improve cognitive/perceptual symptoms and odd behaviors", "Stimulants", "None"]', 1, 'The only personality disorder where antipsychotics have a strong evidence base. (First Aid)'),
    (v_topic_id, '36: Cluster A PDs overlap clinically. Summary: Paranoid = ?, Schizoid = ?, Schizotypal = ?', '["Angry, Sad, Happy", "Paranoid = Suspicious/Distrustful; Schizoid = Detached/Apathetic; Schizotypal = Eccentric/Magical", "None", "None"]', 1, 'The core triad of Cluster A. (MGH Pocket)'),
    (v_topic_id, '37: A patient brings a lawsuit against his neighbor because he believes the neighbor''s dog barking is a calculated plot to destroy his hearing. He has sued 4 other neighbors previously. Diagnosis?', '["OCD", "Paranoid Personality Disorder", "Antisocial PD", "None"]', 1, 'Litigiousness is extremely common in PPD. (Kaplan & Sadock)'),
    (v_topic_id, '38: A patient is described as "aloof" and "indifferent." He works from home as a software tester, avoids team meetings, and tells his doctor he feels no desire to date. Diagnosis?', '["Avoidant PD", "Schizoid Personality Disorder", "Schizotypal PD", "None"]', 1, 'He does not desire connection. (First Aid)'),
    (v_topic_id, '39: A patient insists that he saw an aura around the doctor and that he felt a "vibration" in the room indicating a bad omen. He is highly anxious despite multiple visits. Diagnosis?', '["Schizophrenia", "Schizotypal Personality Disorder", "Panic Disorder", "None"]', 1, 'Illusions and bodily illusions are classic. (MGH Pocket)'),
    (v_topic_id, '40: Can someone be diagnosed with a Cluster A disorder if they are actively in the acute phase of Schizophrenia?', '["Yes", "No, Personality Disorders should not be diagnosed if the symptoms occur EXCLUSIVELY during the course of Schizophrenia or Bipolar Disorder with Psychosis", "None", "None"]', 1, 'The PD must have been present before the onset of the psychotic disorder. (DSM-5)'),
    (v_topic_id, '41: What is the most common reason a patient with a Cluster A personality disorder comes to medical attention?', '["To get friends", "They are brought in by family members, or they present for a comorbid condition (e.g., severe depression or anxiety)", "None", "None"]', 1, 'Egosyntonic nature prevents self-referral. (Kaplan & Sadock)'),
    (v_topic_id, '42: PPD (Paranoid PD) vs. Delusional Disorder vs. Schizophrenia. Which one has generalized, non-bizarre suspicions but no fixed delusions?', '["Schizophrenia", "Paranoid Personality Disorder", "Delusional Disorder", "None"]', 1, 'PPD lacks the absolute certainty of a delusion. (First Aid)'),
    (v_topic_id, '43: A doctor attempts to build rapport with a Paranoid Personality Disorder patient by making a lighthearted joke. The patient storms out. Why?', '["He didn''t get it", "PPD patients lack a sense of humor and often misinterpret jokes as hidden insults or mockery", "He was tired", "None"]', 1, 'Maintain a professional demeanor. (MGH Pocket)'),
    (v_topic_id, '44: Which Cluster A disorder is most likely to join an esoteric cult or fringe religious movement?', '["Schizoid", "Schizotypal Personality Disorder", "Paranoid", "None"]', 1, 'Due to their magical thinking and need for a place that accepts their eccentricities. (Kaplan & Sadock)'),
    (v_topic_id, '45: A Schizoid patient''s lack of emotional reactivity is best described as:', '["Lability", "Affective flattening or blunting", "Anhedonia", "None"]', 1, 'They appear robotic. (First Aid)'),
    (v_topic_id, '46: In Schizotypal PD, what is an "illusion" vs a "hallucination"?', '["They are the same", "An illusion is a misinterpretation of a REAL external stimulus (e.g., a shadow looks like a ghost). A hallucination occurs WITHOUT external stimulus.", "None", "None"]', 1, 'Illusions are common in Schizotypal PD. (MGH Pocket)'),
    (v_topic_id, '47: Do patients with Schizoid PD have impaired reality testing?', '["Yes", "No, their reality testing remains fully intact", "Sometimes", "None"]', 1, 'They know what is real; they just don''t care to interact with it. (Kaplan & Sadock)'),
    (v_topic_id, '48: How do patients with Paranoid PD function in the workplace?', '["Very well", "Often poorly; they have trouble working with authority figures or teams due to constant suspicion of exploitation", "They don''t work", "None"]', 1, 'Often fired for insubordination or fighting. (First Aid)'),
    (v_topic_id, '49: What is the risk of suicide in Schizotypal Personality Disorder?', '["Low", "Significantly elevated; ~10% of patients die by suicide (similar to Schizophrenia)", "Zero", "None"]', 1, 'Often driven by comorbid depression. (MGH Pocket)'),
    (v_topic_id, '50: A 40yo man lives alone in a cabin in the woods. He traps animals for food. When hikers pass by, he ignores them. He feels perfectly content. Most likely diagnosis?', '["PPD", "Schizoid Personality Disorder", "Agoraphobia", "None"]', 1, 'Classic vignette of the content hermit. (Kaplan & Sadock)'),
    (v_topic_id, '51: If the same 40yo man lived in the cabin because he believed the government was tracking his brainwaves through cell towers, what is the diagnosis?', '["Schizoid", "Schizotypal or Paranoid (depending on bizarre vs non-bizarre nature) or Schizophrenia if fully psychotic", "Avoidant", "None"]', 1, 'The motivation for isolation dictates the diagnosis. (First Aid)'),
    (v_topic_id, '52: What psychotherapeutic modality is most challenging but potentially beneficial for Cluster A patients?', '["Group therapy", "Supportive psychotherapy focusing on reality testing, social skills, and managing anxiety. Group therapy is often counterproductive initially.", "Psychoanalysis", "None"]', 1, 'Group therapy triggers intense anxiety/paranoia in these patients. (MGH Pocket)'),
    (v_topic_id, '53: How prevalent are Personality Disorders in the general population?', '["1%", "Approximately 10-15%", "50%", "0.1%"]', 1, 'Highly prevalent, especially in psychiatric settings. (Kaplan & Sadock)'),
    (v_topic_id, '54: Cluster A disorders are characterized by deficits in which major psychological domain?', '["Emotional regulation", "Interpersonal relatedness and reality testing (eccentricity)", "Impulse control", "None"]', 1, 'They struggle to connect with the shared social reality. (First Aid)'),
    (v_topic_id, '55: A patient with Schizotypal PD speaks using unusual words, like saying "I must depart from this location" instead of "I need to leave." This is an example of:', '["Mutism", "Odd, overly formal, or stilted speech", "Aphasia", "None"]', 1, 'A hallmark of the disorder. (MGH Pocket)'),
    (v_topic_id, '56: A patient with PPD refuses a prescribed medication because it is a generic brand, suspecting the doctor gets a kickback. Appropriate response?', '["Yell at them", "Validate their concern neutrally, explain the bioequivalence objectively, and offer the name brand if possible without arguing", "Ignore them", "None"]', 1, 'Avoid power struggles. (Kaplan & Sadock)'),
    (v_topic_id, '57: Which personality disorder has the strongest genetic link to Schizophrenia?', '["Antisocial", "Schizotypal Personality Disorder", "Avoidant", "None"]', 1, 'Considered part of the Schizophrenia spectrum. (First Aid)'),
    (v_topic_id, '58: Which personality disorder is more common in men (Cluster A)?', '["All of them are equally common", "Schizoid and Paranoid PDs are diagnosed slightly more often in males", "None", "None"]', 1, 'Epidemiology fact. (MGH Pocket)'),
    (v_topic_id, '59: A Schizoid patient develops a medical illness requiring long-term hospitalization. What is the main psychological risk?', '["Mania", "Severe anxiety/decompensation from forced social interaction with medical staff", "Psychosis", "None"]', 1, 'Hospitals strip away their defensive isolation. (Kaplan & Sadock)'),
    (v_topic_id, '60: Are there any FDA-approved medications specifically for Personality Disorders?', '["Yes, SSRIs", "No. Medications are used entirely off-label to target specific symptoms (e.g., antidepressants for comorbid MDD, antipsychotics for paranoia)", "Lithium", "None"]', 1, 'Therapy is the only true treatment. (First Aid)'),
    (v_topic_id, '61: Can Schizoid PD patients have a rich inner fantasy life?', '["No", "Yes, they often have elaborate, complex inner fantasy worlds, but they do not share them with others", "None", "None"]', 1, 'The "secret" inner life of the Schizoid. (MGH Pocket)'),
    (v_topic_id, '62: Ideas of reference (Schizotypal) vs Delusions of reference (Schizophrenia)?', '["They are the same", "Ideas of reference can be challenged by logic (''Maybe the TV host wasn''t really winking at me''). Delusions are completely fixed.", "None", "None"]', 1, 'Insight is the key difference. (Kaplan & Sadock)'),
    (v_topic_id, '63: Paranoid Personality Disorder patients often harbor unwarranted doubts about the loyalty of:', '["Dogs", "Friends and associates", "No one", "None"]', 1, 'They keep testing their friends until the friends leave, "proving" the paranoia. (First Aid)'),
    (v_topic_id, '64: A common comorbid condition found with Schizotypal Personality Disorder is:', '["OCD", "Major Depressive Disorder (present in up to 50% of patients)", "Bipolar", "None"]', 1, 'Chronic social isolation leads to depression. (MGH Pocket)'),
    (v_topic_id, '65: Can a patient with PPD be successfully treated with Psychoanalysis?', '["Yes", "No, exploring deep unconscious motives will severely exacerbate their paranoia", "None", "None"]', 1, 'Supportive, here-and-now therapy is best. (Kaplan & Sadock)'),
    (v_topic_id, '66: Schizotypal PD patients often experience "Bodily Illusions." What does this mean?', '["Seizures", "Sensing the presence of a ''force'' or feeling physical sensations not caused by a real stimulus, but without full delusional conviction", "None", "None"]', 1, '"I feel like someone is standing right behind me." (First Aid)'),
    (v_topic_id, '67: How do Schizoid PD patients perform in school/academics?', '["Poorly", "Often very well, especially in fields requiring solitary work (e.g., mathematics, computer programming)", "They drop out", "None"]', 1, 'Their intellect is intact. (MGH Pocket)'),
    (v_topic_id, '68: What is the defining diagnostic requirement regarding the ONSET of a personality disorder?', '["Begins in late life", "The pattern must be traced back to at least adolescence or early adulthood", "Begins at birth", "None"]', 1, 'It is a developmental trajectory. (DSM-5)'),
    (v_topic_id, '69: The "Pervasive" criterion of PDs means:', '["It happens once a year", "The maladaptive traits manifest in a wide variety of personal, social, and occupational situations", "Only at home", "None"]', 1, 'You can''t just be paranoid at work but normal at home. (Kaplan & Sadock)'),
    (v_topic_id, '70: A Paranoid PD patient accuses the therapist of colluding with the patient''s employer. How should the therapist react?', '["Admit to it", "Non-defensively explore the patient''s feelings without directly arguing against the accusation immediately", "End the session", "None"]', 1, 'Arguing proves you are "in on it." (First Aid)'),
    (v_topic_id, '71: What is "Telepathy" in the context of Schizotypal PD?', '["A real power", "The belief that they can read minds or that others can read their minds (magical thinking)", "None", "None"]', 1, 'A classic eccentric belief. (MGH Pocket)'),
    (v_topic_id, '72: Schizoid patients show indifference to:', '["Food", "Both praise and criticism from others", "Pain", "None"]', 1, 'They truly do not care what others think of them. (Kaplan & Sadock)'),
    (v_topic_id, '73: A 22-year-old says, "I know the lotto numbers because the wind blew the leaves into a 7." Diagnosis?', '["PPD", "Schizotypal Personality Disorder", "Antisocial", "None"]', 1, 'Magical thinking/ideas of reference. (First Aid)'),
    (v_topic_id, '74: Can Schizoid PD be diagnosed if the symptoms are due to Autism Spectrum Disorder?', '["Yes", "No, ASD is an exclusion criterion if it better explains the symptoms", "None", "None"]', 1, 'Diagnostic hierarchy. (DSM-5)'),
    (v_topic_id, '75: Paranoid PD patients are at a higher risk of developing which other psychiatric disorder later in life?', '["MDD", "Delusional Disorder or Schizophrenia", "Anorexia", "None"]', 1, 'Paranoia can crystalize into fixed delusions. (MGH Pocket)'),
    (v_topic_id, '76: Is Paranoid PD more common in men or women?', '["Women", "Men", "Equal", "None"]', 1, 'Higher prevalence in males. (Kaplan & Sadock)'),
    (v_topic_id, '77: What happens to Schizotypal symptoms as the patient ages?', '["They cure themselves", "A small percentage decompensate into Schizophrenia, but most remain stable with chronic, lifelong eccentricities", "They become manic", "None"]', 1, 'Lifelong chronicity. (First Aid)'),
    (v_topic_id, '78: Schizoid PD is characterized by a "restricted range of emotional expression" which presents as:', '["Crying", "Lacking spontaneous smiles or nods, rarely reciprocating gestures/facial expressions", "Screaming", "None"]', 1, 'The "blank" face. (MGH Pocket)'),
    (v_topic_id, '79: PPD patients tend to be hypervigilant. What does this mean?', '["They sleep a lot", "Constantly scanning the environment for threats or evidence of betrayal", "They see ghosts", "None"]', 1, 'They are exhausted by their own suspicion. (Kaplan & Sadock)'),
    (v_topic_id, '80: Summary statement for Cluster A:', '["Wild, emotional", "Odd, eccentric, socially isolated, and suspicious", "Anxious, fearful", "None"]', 1, 'The foundation of the cluster. (First Aid)'),
    -- SECTION 2: Cluster B (81-200)
    (v_topic_id, '81: What is the defining feature of Antisocial Personality Disorder (ASPD)?', '["Severe social anxiety", "A pervasive pattern of disregard for and violation of the rights of others, occurring since age 15", "Attention seeking", "None"]', 1, 'Often involves criminal behavior and deceitfulness. (DSM-5)'),
    (v_topic_id, '82: What age must a patient be to receive a diagnosis of Antisocial Personality Disorder?', '["12", "At least 18 years old", "21", "25"]', 1, 'Before age 18, the diagnosis is Conduct Disorder. (First Aid)'),
    (v_topic_id, '83: To diagnose ASPD in an adult, what must be present in their childhood history?', '["ADHD", "Evidence of Conduct Disorder with onset before age 15", "Autism", "None"]', 1, 'ASPD is a continuation of Conduct Disorder. (Kaplan & Sadock)'),
    (v_topic_id, '84: A 16-year-old boy is repeatedly arrested for stealing cars, getting into physical fights, and torturing neighborhood cats. Diagnosis?', '["Antisocial PD", "Conduct Disorder", "Oppositional Defiant Disorder", "None"]', 1, 'Cannot be ASPD because he is under 18. (MGH Pocket)'),
    (v_topic_id, '85: Which of the following is NOT a criterion for Antisocial Personality Disorder?', '["Deceitfulness (repeated lying, use of aliases)", "Impulsivity or failure to plan ahead", "Intense fear of abandonment", "Lack of remorse"]', 2, 'Fear of abandonment is classic for Borderline PD, not ASPD. (Kaplan & Sadock)'),
    (v_topic_id, '86: Patients with ASPD often display a "lack of remorse." What does this mean?', '["They cry often", "They are indifferent to or rationalize having hurt, mistreated, or stolen from another", "They apologize too much", "None"]', 1, 'A core feature of psychopathy. (First Aid)'),
    (v_topic_id, '87: What is the relationship between ASPD and "Psychopathy" (or Sociopathy)?', '["They are the exact same", "Psychopathy is a related but more severe construct focusing on lack of empathy and grandiosity; not all ASPD patients are psychopaths", "None", "None"]', 1, 'ASPD focuses more on observable behaviors (crimes, impulsivity). (MGH Pocket)'),
    (v_topic_id, '88: Which gender is more frequently diagnosed with Antisocial Personality Disorder?', '["Women", "Men (by a wide margin, up to 3x more common)", "Equal", "None"]', 1, 'Highly prevalent in prison populations. (Kaplan & Sadock)'),
    (v_topic_id, '89: A patient with ASPD presents to the ER requesting opioids for "severe back pain," but imaging is negative and he is seen pacing the room comfortably. How should the physician respond?', '["Give opioids", "Maintain firm, objective boundaries, deny the inappropriate request, and avoid arguing or being intimidated", "Call the police immediately", "None"]', 1, 'They often try to manipulate or threaten healthcare workers. (First Aid)'),
    (v_topic_id, '90: What is the classic course of Antisocial Personality Disorder as the patient ages?', '["It gets worse", "Symptoms often decrease or ''''burn out'''' by the 4th decade of life (age 40+), particularly criminal behaviors", "It turns into schizophrenia", "None"]', 1, 'Older ASPD patients commit fewer crimes, though interpersonal deficits remain. (MGH Pocket)'),
    (v_topic_id, '91: Which neurobiological finding is often associated with Antisocial Personality Disorder?', '["Enlarged ventricles", "Decreased frontal lobe volume/activity (impairing impulse control and executive function)", "Cerebellar atrophy", "None"]', 1, 'They have biological deficits in fear conditioning. (Kaplan & Sadock)'),
    (v_topic_id, '92: What is the best treatment for Antisocial Personality Disorder?', '["SSRIs", "There is no standard effective treatment; psychotherapy is generally ineffective because they do not believe they have a problem and often manipulate the therapist", "Lithium", "None"]', 1, 'Often, treatment is mandated by the court system. (First Aid)'),
    (v_topic_id, '93: Borderline Personality Disorder (BPD) is characterized by a pervasive pattern of instability in which three domains?', '["Sleep, eating, exercise", "Interpersonal relationships, self-image, and affects (emotions), along with marked impulsivity", "Memory, attention, language", "None"]', 1, 'The core triad of BPD. (DSM-5)'),
    (v_topic_id, '94: A classic defense mechanism used by patients with Borderline Personality Disorder is:', '["Sublimation", "Splitting (seeing people as entirely ''''all good'''' or ''''all bad'''', with no grey area)", "Intellectualization", "None"]', 1, 'A defense against the anxiety of ambivalence. (Kaplan & Sadock)'),
    (v_topic_id, '95: In a hospital setting, how might "splitting" present?', '["The patient refuses to eat", "The patient tells the day nurse she is an angel, but tells the night nurse she is evil, causing staff conflict", "The patient hides", "None"]', 1, 'Staff must maintain unified, consistent communication to manage this. (First Aid)'),
    (v_topic_id, '96: Patients with Borderline PD often make frantic efforts to avoid:', '["Crowds", "Real or imagined abandonment", "Spiders", "None"]', 1, 'The root of their intense interpersonal clinginess and subsequent rage. (MGH Pocket)'),
    (v_topic_id, '97: Which of the following is a hallmark criteria for Borderline PD regarding self-harm?', '["Binge eating only", "Recurrent suicidal behavior, gestures, or threats, or non-suicidal self-injury (e.g., cutting)", "Refusing medication", "None"]', 1, 'A major reason for frequent psychiatric admissions. (Kaplan & Sadock)'),
    (v_topic_id, '98: Why do patients with Borderline Personality Disorder often engage in cutting (NSSI)?', '["To die", "Often to relieve intense emotional pain, feel ''''real'''' during dissociative episodes, or elicit caregiving from others", "To get high", "None"]', 1, 'It is an extreme coping mechanism for emotional dysregulation. (First Aid)'),
    (v_topic_id, '99: Affective instability in Borderline PD is characterized by:', '["Lasting for months (like depression)", "Intense episodic dysphoria, irritability, or anxiety usually lasting a few hours and rarely more than a few days", "Complete emotional flatness", "None"]', 1, 'Highly reactive to environmental triggers (unlike Bipolar disorder). (MGH Pocket)'),
    (v_topic_id, '100: Patients with Borderline PD often describe a chronic feeling of:', '["Joy", "Emptiness", "Hunger", "None"]', 1, 'A deep, painful sense of having no core identity. (Kaplan & Sadock)'),
    (v_topic_id, '101: Under severe stress, a patient with Borderline PD may experience transient:', '["Mania", "Stress-related paranoid ideation or severe dissociative symptoms", "Seizures", "None"]', 1, 'Often resolves when the stressor is removed. (First Aid)'),
    (v_topic_id, '102: What is the gold-standard psychotherapy for Borderline Personality Disorder?', '["Psychoanalysis", "Dialectical Behavior Therapy (DBT)", "Exposure Therapy", "None"]', 1, 'Developed by Marsha Linehan specifically for BPD. (MGH Pocket)'),
    (v_topic_id, '103: Dialectical Behavior Therapy (DBT) focuses on four main modules: Mindfulness, Interpersonal Effectiveness, Emotion Regulation, and:', '["Dream analysis", "Distress Tolerance", "Weight loss", "None"]', 1, 'Teaching them how to tolerate emotional pain without cutting or attempting suicide. (Kaplan & Sadock)'),
    (v_topic_id, '104: Are medications effective for curing Borderline Personality Disorder?', '["Yes, SSRIs cure it", "No, medications only treat comorbid conditions (e.g., antidepressants for MDD) or target specific symptoms (e.g., low-dose antipsychotics for severe anger/dissociation)", "None", "None"]', 1, 'Therapy (DBT) is the primary treatment. (First Aid)'),
    (v_topic_id, '105: What is the completed suicide rate in Borderline Personality Disorder?', '["0%", "Approximately 10%", "50%", "100%"]', 1, 'Very high mortality rate, often resulting from impulsive overdoses. (MGH Pocket)'),
    (v_topic_id, '106: Borderline Personality Disorder is highly comorbid with which other psychiatric condition?', '["Schizophrenia", "Major Depressive Disorder, Substance Use Disorders, and Eating Disorders", "Autism", "None"]', 1, 'Polypharmacy is common but should be avoided. (Kaplan & Sadock)'),
    (v_topic_id, '107: A 24-year-old woman is furious that her therapist was 5 minutes late, screaming that the therapist "never cared about her." Ten minutes later, she is crying and begging the therapist not to leave her. Diagnosis?', '["Histrionic PD", "Borderline Personality Disorder", "Bipolar I", "None"]', 1, 'Intense, unstable relationships and fear of abandonment. (First Aid)'),
    (v_topic_id, '108: Histrionic Personality Disorder is defined by a pervasive pattern of:', '["Suspicion", "Excessive emotionality and attention-seeking behavior", "Apathy", "None"]', 1, 'Must be the center of attention. (DSM-5)'),
    (v_topic_id, '109: How do patients with Histrionic Personality Disorder act when they are NOT the center of attention?', '["They are happy", "They feel uncomfortable and unappreciated, often doing something dramatic to regain the spotlight", "They fall asleep", "None"]', 1, 'Constant need for validation. (Kaplan & Sadock)'),
    (v_topic_id, '110: A classic interaction style for someone with Histrionic PD involves behavior that is:', '["Cold and detached", "Inappropriately sexually seductive or provocative", "Violent and aggressive", "None"]', 1, 'Used to draw attention to themselves. (First Aid)'),
    (v_topic_id, '111: Speech in Histrionic Personality Disorder is often described as:', '["Poverty of speech", "Excessively impressionistic and lacking in detail (e.g., ''''It was the most amazing thing ever!'''' but unable to explain why)", "Word salad", "None"]', 1, 'Shallow, dramatic communication. (MGH Pocket)'),
    (v_topic_id, '112: How do patients with Histrionic PD view their relationships?', '["As unimportant", "They consider relationships to be much more intimate than they actually are (e.g., calling the doctor their ''''best friend'''')", "As threatening", "None"]', 1, 'Superficial attachment. (Kaplan & Sadock)'),
    (v_topic_id, '113: Which defense mechanism is classically associated with Histrionic PD?', '["Intellectualization", "Regression (reverting to childlike behavior) and Repression", "Sublimation", "None"]', 1, 'Using emotions to avoid deeper psychological pain. (First Aid)'),
    (v_topic_id, '114: Histrionic PD vs Borderline PD. Which one involves deep feelings of emptiness, self-harm, and severe identity disturbance?', '["Histrionic", "Borderline Personality Disorder", "Both", "None"]', 1, 'Histrionic patients are dramatic but do not typically have the severe self-destructiveness or profound emptiness of BPD. (MGH Pocket)'),
    (v_topic_id, '115: Narcissistic Personality Disorder is defined by a pervasive pattern of:', '["Social isolation", "Grandiosity (in fantasy or behavior), need for admiration, and lack of empathy", "Self-harm", "None"]', 1, 'Believes they are "special" and unique. (DSM-5)'),
    (v_topic_id, '116: How does a patient with Narcissistic PD typically react to criticism?', '["They ignore it", "With intense rage, counterattack, or profound humiliation (''''narcissistic injury'''')", "They agree with it", "None"]', 1, 'Their fragile self-esteem cannot handle being flawed. (Kaplan & Sadock)'),
    (v_topic_id, '117: What is the underlying psychological structure of Narcissistic Personality Disorder?', '["True self-love", "A profoundly fragile self-esteem that requires constant external validation to maintain a grandiose facade", "Psychosis", "None"]', 1, 'The grandiosity is a defense mechanism. (First Aid)'),
    (v_topic_id, '118: A patient demands to only be seen by the "Chief of Medicine" because the residents are "too incompetent to understand my complex case." Diagnosis?', '["Borderline PD", "Narcissistic Personality Disorder", "Schizoid PD", "None"]', 1, 'Belief that they can only be understood by high-status people. (MGH Pocket)'),
    (v_topic_id, '119: What is the difference between Narcissistic PD and Antisocial PD regarding the exploitation of others?', '["Only ASPD exploits", "ASPD exploits for material gain or power. NPD exploits others to enhance their own self-esteem and extract admiration.", "None", "None"]', 1, 'Motivation differs. (Kaplan & Sadock)'),
    (v_topic_id, '120: Do patients with Narcissistic PD have empathy for others?', '["Yes, too much", "No, they are often unwilling to recognize or identify with the feelings and needs of others", "Sometimes", "None"]', 1, 'A core deficit. (First Aid)'),
    (v_topic_id, '121: Narcissistic PD patients are often envious of others, but they also believe:', '["That no one is envious of them", "That others are highly envious of THEM", "That envy is a sin", "None"]', 1, 'Projection of their own envy. (MGH Pocket)'),
    (v_topic_id, '122: Aging is particularly difficult for which Cluster B personality disorder?', '["Borderline", "Narcissistic PD (loss of beauty, power, or youth can trigger severe depression or narcissistic crisis)", "Antisocial", "None"]', 1, 'Midlife crises are often severe. (Kaplan & Sadock)'),
    (v_topic_id, '123: Summary statement for Cluster B:', '["Odd, eccentric", "Dramatic, emotional, erratic, and unpredictable", "Anxious, fearful", "None"]', 1, 'The core of the cluster. (First Aid)'),
    (v_topic_id, '124: A 30-year-old man constantly lies to his girlfriend, recently stole her credit card to buy a watch, and feels no guilt when she cries about it. He has a history of juvenile detention. Diagnosis?', '["Narcissistic PD", "Antisocial Personality Disorder", "Bipolar Disorder", "None"]', 1, 'Classic ASPD presentation. (MGH Pocket)'),
    (v_topic_id, '125: A 22-year-old woman cuts her wrists after her boyfriend says he needs to work late. She is terrified he is leaving her. She has a history of unstable relationships and impulsive spending. Diagnosis?', '["Histrionic PD", "Borderline Personality Disorder", "Depression", "None"]', 1, 'Classic BPD presentation. (Kaplan & Sadock)'),
    (v_topic_id, '126: A 28-year-old woman comes to the clinic wearing a bright red sequin dress and heavy makeup. She flirts with the doctor and dramatically faints when told she has a mild cold. Diagnosis?', '["Borderline PD", "Histrionic Personality Disorder", "Factitious Disorder", "None"]', 1, 'Classic Histrionic presentation. (First Aid)'),
    (v_topic_id, '127: A 45-year-old CEO belittles his staff, insists his ideas are infallible, and fires anyone who disagrees with him because they are "jealous of his brilliance." Diagnosis?', '["Antisocial PD", "Narcissistic Personality Disorder", "OCPD", "None"]', 1, 'Classic NPD presentation. (MGH Pocket)'),
    (v_topic_id, '128: What is "Projective Identification"?', '["A type of memory loss", "A primitive defense where the patient projects an intolerable aspect of themselves onto the therapist, and the therapist subconsciously begins to act out that projection", "None", "None"]', 1, 'Common in BPD. E.g., projecting anger, causing the therapist to actually feel inexplicably angry. (Kaplan & Sadock)'),
    (v_topic_id, '129: What is the most common reason a patient with ASPD presents to a psychiatrist?', '["They want to stop committing crimes", "Usually court-ordered, or seeking secondary gain (e.g., getting a letter for disability, avoiding jail, getting controlled substances)", "None", "None"]', 1, 'Always look for the secondary gain. (First Aid)'),
    (v_topic_id, '130: BPD patients often have a history of what in childhood?', '["Perfect childhood", "Severe childhood trauma, physical/sexual abuse, or profound neglect", "High academic achievement", "None"]', 1, 'Trauma is a massive risk factor for developing BPD. (MGH Pocket)'),
    (v_topic_id, '131: How should a physician handle a Borderline patient who calls the office 10 times a day in a crisis?', '["Block their number", "Establish clear, consistent, and firm boundaries. Schedule regular brief appointments rather than responding to crises on demand.", "Prescribe Benzos", "None"]', 1, 'Consistency prevents burnout and provides structure. (Kaplan & Sadock)'),
    (v_topic_id, '132: Histrionic PD patients are often highly suggestible. What does this mean?', '["They are stubborn", "They are easily influenced by others or circumstances (e.g., adopting the opinions of whoever they are currently talking to)", "They don''t listen", "None"]', 1, 'Superficial identity. (First Aid)'),
    (v_topic_id, '133: A patient with NPD is told they have diabetes. They refuse to take insulin, stating, "My body is superior, it will heal itself. That disease is for weak people." This is an example of:', '["Psychosis", "Grandiose delusions/denial used to protect fragile self-esteem", "Malingering", "None"]', 1, 'Medical non-compliance is common if the disease threatens their self-image. (MGH Pocket)'),
    (v_topic_id, '134: Antisocial PD vs Bipolar Mania. Both can involve impulsive spending, sexual indiscretions, and fights. How to differentiate?', '["They are the same", "Mania is EPISODIC with a distinct change from baseline, accompanied by decreased need for sleep and pressured speech. ASPD is a lifelong, constant pattern.", "None", "None"]', 1, 'Chronicity vs Episodicity. (Kaplan & Sadock)'),
    (v_topic_id, '135: What role do SSRIs play in Borderline Personality Disorder?', '["They cure the disorder", "They are often used to treat comorbid depression/anxiety, and may take the ''edge'' off impulsivity, but they do NOT fix the core identity/abandonment issues", "None", "None"]', 1, 'Adjunctive treatment only. (First Aid)'),
    (v_topic_id, '136: A key difference between Histrionic PD and Narcissistic PD?', '["Histrionic wants money", "Histrionic wants ATTENTION (even if it''s negative or makes them look fragile). Narcissistic wants ADMIRATION (they must look superior).", "None", "None"]', 1, 'A Histrionic patient will play the victim to get a hug; an NPD patient would never look weak. (MGH Pocket)'),
    (v_topic_id, '137: "Micropsychotic" episodes in BPD usually happen when?', '["Randomly", "During times of severe interpersonal stress (e.g., a breakup)", "When they are manic", "None"]', 1, 'They hear a voice telling them to cut themselves, but it resolves when they calm down. (Kaplan & Sadock)'),
    (v_topic_id, '138: Why are Benzodiazepines generally AVOIDED in Borderline Personality Disorder?', '["They cause seizures", "They can disinhibit the patient, worsening impulsivity and increasing the risk of suicide/self-harm", "They don''t work", "None"]', 1, 'Same reason you don''t give alcohol to someone who is angry. (First Aid)'),
    (v_topic_id, '139: The "ASPD triad" of childhood (Macdonald triad) predicting future psychopathy includes:', '["Bedwetting, playing with dolls, crying", "Enuresis (bedwetting), Cruelty to animals, and Fire-setting", "None", "None"]', 1, 'Historical concept, still conceptually relevant for severe Conduct Disorder. (MGH Pocket)'),
    (v_topic_id, '140: Can a patient have both BPD and NPD?', '["No", "Yes, comorbid personality disorders are extremely common", "None", "None"]', 1, 'They can have severe fear of abandonment AND grandiose entitlement. (Kaplan & Sadock)'),
    (v_topic_id, '141: A classic countertransference reaction a doctor might feel toward an ASPD patient?', '["Love", "Fear, intimidation, or feeling manipulated/conned", "Boredom", "None"]', 1, 'Always monitor your own feelings. (First Aid)'),
    (v_topic_id, '142: A classic countertransference reaction a doctor might feel toward a Borderline patient?', '["Apathy", "Wanting to ''''rescue'''' them, followed by intense frustration and burnout when the patient inevitably acts out", "None", "None"]', 1, 'The "savior complex" trap. (MGH Pocket)'),
    (v_topic_id, '143: A classic countertransference reaction a doctor might feel toward a Narcissistic patient?', '["Joy", "Anger, feeling devalued, or feeling an urge to argue and ''''cut them down to size''''", "None", "None"]', 1, 'Don''t take their insults personally. (Kaplan & Sadock)'),
    (v_topic_id, '144: The impulsivity in BPD must be in at least two areas that are potentially self-damaging. Examples?', '["Reading, writing", "Spending, sex, substance abuse, reckless driving, binge eating", "None", "None"]', 1, 'Part of the diagnostic criteria. (DSM-5)'),
    (v_topic_id, '145: How long must symptoms be present to diagnose a Personality Disorder?', '["1 month", "They must represent an enduring, lifelong pattern starting by early adulthood", "1 week", "None"]', 1, 'Cannot be diagnosed during a single crisis. (First Aid)'),
    (v_topic_id, '146: What is "Narcissistic supply"?', '["Money", "The admiration, attention, or compliance from others that the narcissist requires to regulate their self-esteem", "Drugs", "None"]', 1, 'When the supply runs out, they decompensate. (MGH Pocket)'),
    (v_topic_id, '147: BPD is more commonly diagnosed in which gender?', '["Men", "Women (up to 75% of clinical populations)", "Equal", "None"]', 1, 'Though some argue men are underdiagnosed and instead labeled ASPD. (Kaplan & Sadock)'),
    (v_topic_id, '148: Histrionic PD is more commonly diagnosed in which gender?', '["Men", "Women", "Equal", "None"]', 1, 'Highly culturally influenced diagnosis. (First Aid)'),
    (v_topic_id, '149: ASPD vs Narcissistic PD regarding rules and laws?', '["NPD breaks more laws", "ASPD breaks rules for gain/thrill and lacks a moral compass. NPD breaks rules because they believe they are ''''above the law'''' and rules don''''t apply to them.", "None", "None"]', 1, 'Entitlement vs true sociopathy. (MGH Pocket)'),
    (v_topic_id, '150: Do Histrionic patients truly experience the deep emotions they display?', '["Yes", "No, their emotional expression is shallow and rapidly shifting", "None", "None"]', 1, 'It is a performance. (Kaplan & Sadock)'),
    (v_topic_id, '151: A Borderline patient slashes her arms after a fight with her mother. The ER doctor stitches her up. The patient asks, "Do you think I''''m a bad person?" Best response?', '["Yes, this was stupid", "Validate her distress neutrally, avoid reinforcing the self-harm with excessive sympathy, and focus on coping skills", "Ignore her", "None"]', 1, 'Reinforcing the behavior will guarantee she returns. (First Aid)'),
    (v_topic_id, '152: In DBT, what does "Radical Acceptance" mean?', '["Giving up", "Accepting reality exactly as it is, without judging it or fighting it, to reduce suffering", "Fighting back", "None"]', 1, 'A core mindfulness skill. (MGH Pocket)'),
    (v_topic_id, '153: The term "Borderline" originally meant on the border between:', '["Life and death", "Neurosis (anxiety) and Psychosis (schizophrenia)", "Mood and personality", "None"]', 1, 'Historical context of the name. (Kaplan & Sadock)'),
    (v_topic_id, '154: A hallmark of Narcissistic PD is a sense of entitlement. This means:', '["They work hard", "Unreasonable expectations of especially favorable treatment or automatic compliance with their expectations", "None", "None"]', 1, '"I shouldn''t have to wait in the waiting room." (First Aid)'),
    (v_topic_id, '155: Good prognostic factors for BPD?', '["Substance abuse", "Higher intelligence, absence of substance abuse, and ability to engage in long-term DBT", "None", "None"]', 1, 'Many BPD patients DO improve significantly by their 30s-40s with treatment. (MGH Pocket)'),
    (v_topic_id, '156: Can someone with ASPD be a successful CEO or politician?', '["No", "Yes, ''''corporate psychopaths'''' exist who utilize ruthlessness, superficial charm, and lack of empathy to climb the corporate ladder without breaking explicit laws", "None", "None"]', 1, 'Subclinical ASPD. (Kaplan & Sadock)'),
    (v_topic_id, '157: A Histrionic patient says, "My life is ruined, my boyfriend left me, I am going to die!" but 5 minutes later is laughing at a meme on her phone. This is:', '["Mania", "Shallow, rapidly shifting affect", "Schizophrenia", "None"]', 1, 'Diagnostic for Cluster B. (First Aid)'),
    (v_topic_id, '158: Narcissistic patients often choose friends/partners based on:', '["Love", "How that person enhances their own status (e.g., ''''trophy wife'''', associating only with top-tier institutions)", "None", "None"]', 1, 'People are treated as objects to reflect their glory. (MGH Pocket)'),
    (v_topic_id, '159: What is the risk of suicide in Narcissistic PD?', '["Zero", "High during a severe narcissistic crisis (e.g., public disgrace, bankruptcy, loss of career)", "None", "None"]', 1, 'When the false self shatters, they have no defense. (Kaplan & Sadock)'),
    (v_topic_id, '160: Summary statement for Borderline PD:', '["Loves themselves", "I hate you, don''''t leave me", "I want to be alone", "None"]', 1, 'The classic textbook phrase summarizing the push-pull dynamic. (First Aid)'),
    -- SECTION 3: Cluster C (161-240)
    (v_topic_id, '161: What is the defining feature of Avoidant Personality Disorder?', '["A pervasive pattern of social inhibition, feelings of inadequacy, and hypersensitivity to negative evaluation", "A pervasive pattern of grandiosity", "Social isolation due to lack of interest in others", "None"]', 1, 'They WANT friends but are terrified of rejection. (DSM-5)'),
    (v_topic_id, '162: How does Avoidant Personality Disorder differ from Schizoid Personality Disorder?', '["They are the same", "Avoidant patients desire relationships and feel lonely; Schizoid patients do not desire relationships and feel content alone", "None", "None"]', 1, 'The motivation for isolation is key. (First Aid)'),
    (v_topic_id, '163: Avoidant Personality Disorder is often considered to be on a continuum with which anxiety disorder?', '["Panic Disorder", "Social Anxiety Disorder (Social Phobia)", "Agoraphobia", "None"]', 1, 'Some consider them variants of the same condition. (MGH Pocket)'),
    (v_topic_id, '164: A patient with Avoidant Personality Disorder will typically only get involved with people if:', '["They are forced to", "They are certain of being liked and accepted without criticism", "They can dominate them", "None"]', 1, 'They require absolute guarantees of no rejection. (Kaplan & Sadock)'),
    (v_topic_id, '165: How do patients with Avoidant PD typically view themselves?', '["As superior to others", "As socially inept, personally unappealing, or inferior to others", "As physically unattractive", "None"]', 1, 'Profound feelings of inadequacy. (First Aid)'),
    (v_topic_id, '166: A 25-year-old man refuses a promotion at work because it requires him to lead team meetings. He fears he will say something stupid and be fired. He has no friends but wishes he did. Diagnosis?', '["Schizoid PD", "Avoidant Personality Disorder", "Dependent PD", "None"]', 1, 'Occupational impairment due to fear of criticism. (MGH Pocket)'),
    (v_topic_id, '167: What is the defining feature of Dependent Personality Disorder?', '["A pervasive pattern of excessive emotionality", "A pervasive and excessive need to be taken care of that leads to submissive and clinging behavior and fears of separation", "Aggression", "None"]', 1, 'They feel unable to function independently. (DSM-5)'),
    (v_topic_id, '168: How do patients with Dependent Personality Disorder typically make everyday decisions (e.g., what to wear)?', '["By flipping a coin", "They have difficulty making everyday decisions without an excessive amount of advice and reassurance from others", "They let the government decide", "None"]', 1, 'They abdicate responsibility for their own lives. (Kaplan & Sadock)'),
    (v_topic_id, '169: A patient with Dependent Personality Disorder is in a highly abusive relationship. Why do they often stay?', '["They enjoy the abuse", "Due to an intense fear of being left to care for themselves; they will tolerate abuse to maintain the relationship", "None", "None"]', 1, 'A major clinical concern for these patients. (First Aid)'),
    (v_topic_id, '170: What happens when a close relationship ends for a patient with Dependent PD?', '["They are relieved", "They urgently seek another relationship as a source of care and support", "They become violent", "None"]', 1, 'They cannot tolerate being alone. (MGH Pocket)'),
    (v_topic_id, '171: Dependent PD vs Borderline PD regarding abandonment?', '["They are the same", "BPD reacts to abandonment with rage, emptiness, and self-harm. Dependent PD reacts with submissiveness and urgently seeking a replacement.", "None", "None"]', 1, 'Different coping mechanisms for the same fear. (Kaplan & Sadock)'),
    (v_topic_id, '172: Dependent PD vs Avoidant PD?', '["They are the same", "Avoidant avoids relationships until certain of acceptance. Dependent desperately seeks out and clings to relationships.", "None", "None"]', 1, 'Opposite approaches to interpersonal connection. (First Aid)'),
    (v_topic_id, '173: What is the defining feature of Obsessive-Compulsive Personality Disorder (OCPD)?', '["True obsessions and compulsions", "A pervasive pattern of preoccupation with orderliness, perfectionism, and mental/interpersonal control, at the expense of flexibility, openness, and efficiency", "None", "None"]', 1, 'The "control freak" disorder. (DSM-5)'),
    (v_topic_id, '174: How does OCPD differ from Obsessive-Compulsive Disorder (OCD)?', '["They are the same", "OCD involves true intrusive obsessions and ritualistic compulsions (egodystonic). OCPD involves rigid perfectionism and orderliness (egosyntonic) WITHOUT true obsessions/compulsions.", "None", "None"]', 1, 'Crucial distinction. OCPD patients think their way is the right way. (MGH Pocket)'),
    (v_topic_id, '175: A patient spends 3 hours rewriting a 1-paragraph email to their boss to make sure it is "perfect," ultimately missing the deadline. Diagnosis?', '["ADHD", "Obsessive-Compulsive Personality Disorder (OCPD)", "Narcissistic PD", "None"]', 1, 'Perfectionism that interferes with task completion. (First Aid)'),
    (v_topic_id, '176: How do patients with OCPD typically handle delegating tasks at work?', '["They delegate everything", "They are reluctant to delegate tasks or work with others unless they submit EXACTLY to their way of doing things", "They form committees", "None"]', 1, '"If you want it done right, do it yourself." (Kaplan & Sadock)'),
    (v_topic_id, '177: What is the typical attitude of a patient with OCPD toward money?', '["They spend it recklessly", "They adopt a miserly spending style toward both self and others; money is viewed as something to be hoarded for future catastrophes", "None", "None"]', 1, 'Extreme frugality. (MGH Pocket)'),
    (v_topic_id, '178: Patients with OCPD are often excessively devoted to:', '["Leisure activities", "Work and productivity, to the exclusion of leisure activities and friendships", "Sleep", "None"]', 1, 'The classic workaholic. (First Aid)'),
    (v_topic_id, '179: A patient keeps stacks of old newspapers from 1995 in their living room because "I might need to read them someday." This is a criterion for which personality disorder?', '["Dependent PD", "Obsessive-Compulsive Personality Disorder (inability to discard worn-out or worthless objects even when they have no sentimental value)", "None", "None"]', 1, 'Hoarding behavior can be part of OCPD (or a separate Hoarding Disorder). (Kaplan & Sadock)'),
    (v_topic_id, '180: The emotional expression of a patient with OCPD is typically:', '["Wild and dramatic", "Rigid, formal, stiff, and lacking in spontaneity", "Joyful", "None"]', 1, 'They are highly uncomfortable with unpredictable emotions. (MGH Pocket)'),
    (v_topic_id, '181: Which defense mechanisms are classically used by patients with OCPD?', '["Acting out", "Intellectualization, rationalization, and undoing", "Sublimation", "None"]', 1, 'Used to distance themselves from messy emotions. (First Aid)'),
    (v_topic_id, '182: A 40-year-old accountant is described by his wife as "stubborn" and "inflexible." He insists they eat dinner at exactly 6:00 PM every day and becomes angry if plans change. Diagnosis?', '["OCPD", "Autism", "Schizoid", "None"]', 0, 'Rigidity and stubbornness are core criteria. (Kaplan & Sadock)'),
    (v_topic_id, '183: Dependent PD is more frequently diagnosed in which gender?', '["Men", "Women", "Equal", "None"]', 1, 'May reflect cultural biases regarding gender roles. (MGH Pocket)'),
    (v_topic_id, '184: OCPD is more frequently diagnosed in which gender?', '["Women", "Men (about twice as often as women)", "Equal", "None"]', 1, 'Epidemiology. (First Aid)'),
    (v_topic_id, '185: Treatment for Avoidant Personality Disorder?', '["Lithium", "CBT, assertiveness training, and SSRIs/beta-blockers for severe social anxiety", "Psychoanalysis", "None"]', 1, 'Medications can help them engage in therapy. (Kaplan & Sadock)'),
    (v_topic_id, '186: Treatment for Dependent Personality Disorder?', '["ECT", "CBT and insight-oriented therapy to foster independence; must be careful not to let the patient become overly dependent on the therapist", "None", "None"]', 1, 'Therapist must maintain boundaries. (MGH Pocket)'),
    (v_topic_id, '187: Treatment for OCPD?', '["SSRIs (first line)", "Psychotherapy (CBT/psychodynamic); SSRIs can be used off-label if true OCD/MDD is comorbid, but they don''''t cure OCPD", "None", "None"]', 1, 'OCPD patients are very resistant to change. (First Aid)'),
    (v_topic_id, '188: A patient with Avoidant PD wants to go to a party. What will they likely do?', '["Go and be the center of attention", "Avoid going unless they have a trusted friend who guarantees they won''''t be left alone or judged", "Go and fight someone", "None"]', 1, 'They need a "safety person." (Kaplan & Sadock)'),
    (v_topic_id, '189: Cluster C personality disorders are characterized primarily by:', '["Psychosis", "Anxiety and fearfulness", "Grandiosity", "None"]', 1, 'The core of the cluster. (MGH Pocket)'),
    (v_topic_id, '190: A 30-year-old woman stays in a job she hates, where she is constantly belittled by her boss. She refuses to quit because she believes she cannot find another job and needs her boss to tell her what to do. Diagnosis?', '["Avoidant PD", "Dependent Personality Disorder", "Masochistic PD", "None"]', 1, 'Classic DPD occupational impairment. (First Aid)'),
    (v_topic_id, '191: How does an OCPD patient approach morality, ethics, or values?', '["They don''''t care", "They are overconscientious, scrupulous, and inflexible about matters of morality (not accounted for by cultural/religious identification)", "None", "None"]', 1, 'Highly rigid sense of right and wrong. (Kaplan & Sadock)'),
    (v_topic_id, '192: A patient with Avoidant PD feels:', '["Superior", "Socially inept and personally unappealing", "Angry", "None"]', 1, 'Profoundly low self-esteem. (MGH Pocket)'),
    (v_topic_id, '193: Dependent PD patients often volunteer to do unpleasant tasks. Why?', '["They like them", "To gain the favor and support of others, out of fear of losing their care", "To get paid", "None"]', 1, 'They will sacrifice themselves to maintain attachment. (First Aid)'),
    (v_topic_id, '194: An OCPD patient is organizing a family vacation. What is the likely result?', '["A spontaneous, fun trip", "A highly regimented itinerary where the schedule becomes more important than actually enjoying the vacation", "They refuse to go", "None"]', 1, 'Missing the forest for the trees. (Kaplan & Sadock)'),
    (v_topic_id, '195: A patient with Avoidant PD is offered a promotion that requires public speaking. They will likely:', '["Accept it gladly", "Decline the promotion to avoid potential criticism or embarrassment", "Quit their job", "None"]', 1, 'Career stunting is common. (MGH Pocket)'),
    (v_topic_id, '196: Avoidant PD overlaps significantly with which personality disorder, as both involve social withdrawal?', '["Schizotypal", "Schizoid PD (but Avoidant wants friends, Schizoid does not)", "Antisocial", "None"]', 1, 'A classic board comparison. (First Aid)'),
    (v_topic_id, '197: Dependent PD overlaps with Borderline PD. How to distinguish?', '["They don''''t overlap", "Borderline has rage, emptiness, and identity disturbance. Dependent is submissive, passive, and clings without the rage.", "None", "None"]', 1, 'Affective stability differentiates them. (Kaplan & Sadock)'),
    (v_topic_id, '198: OCPD overlaps with Narcissistic PD regarding perfectionism. How to distinguish?', '["NPD is worse", "OCPD is perfectionistic to achieve order and control. NPD is perfectionistic to prove they are superior and gain admiration.", "None", "None"]', 1, 'Different motivations for similar behavior. (MGH Pocket)'),
    (v_topic_id, '199: Can a patient have both OCD and OCPD?', '["No", "Yes, they can co-occur, but they are distinct diagnoses", "None", "None"]', 1, 'OCD = intrusive thoughts/rituals. OCPD = rigid lifestyle. (First Aid)'),
    (v_topic_id, '200: Summary statement for Cluster C:', '["Wild, emotional", "Anxious, fearful, and rigid", "Odd, eccentric", "None"]', 1, 'The anxious cluster. (Kaplan & Sadock)'),
    (v_topic_id, '201: A patient with Avoidant PD fears being shamed or ridiculed. A patient with Paranoid PD fears:', '["Nothing", "Being exploited, harmed, or betrayed", "None", "None"]', 1, 'Different core fears. (MGH Pocket)'),
    (v_topic_id, '202: A Dependent PD patient has difficulty expressing disagreement with others. Why?', '["They don''''t care", "Fear of loss of support or approval", "They agree with everyone", "None"]', 1, 'They will nod along even if they strongly disagree. (First Aid)'),
    (v_topic_id, '203: OCPD patients often struggle to work in teams because:', '["They hate people", "They cannot tolerate others doing things differently than their exact specifications", "They are lazy", "None"]', 1, 'Control is paramount. (Kaplan & Sadock)'),
    (v_topic_id, '204: Which Cluster C disorder is most likely to result in a patient staying in an abusive marriage?', '["OCPD", "Dependent Personality Disorder", "Avoidant", "None"]', 1, 'Due to inability to function alone. (MGH Pocket)'),
    (v_topic_id, '205: Which Cluster C disorder is most likely to result in a patient remaining single and isolated despite desperately wanting a partner?', '["Dependent", "Avoidant Personality Disorder", "OCPD", "None"]', 1, 'Fear of rejection outweighs the desire for connection. (First Aid)'),
    (v_topic_id, '206: A medical student spends 12 hours making a color-coded study schedule but only 2 hours actually studying. This is a trait of:', '["ADHD", "Obsessive-Compulsive Personality Disorder", "Narcissism", "None"]', 1, 'Preoccupation with details/lists such that the major point of the activity is lost. (Kaplan & Sadock)'),
    (v_topic_id, '207: How do Avoidant PD patients react to a neutral or ambiguous comment?', '["They ignore it", "They often misinterpret it as hidden criticism or mockery", "They laugh", "None"]', 1, 'Hypersensitivity to negative evaluation. (MGH Pocket)'),
    (v_topic_id, '208: Dependent PD patients may appear to lack initiative. Why?', '["Laziness", "Lack of self-confidence in their own judgment or abilities, not a lack of motivation", "Low IQ", "None"]', 1, 'They need someone else to start the task for them. (First Aid)'),
    (v_topic_id, '209: OCPD patients often show a profound lack of:', '["Intelligence", "Flexibility, openness, and efficiency", "Money", "None"]', 1, 'Their rigidity makes them highly inefficient. (Kaplan & Sadock)'),
    (v_topic_id, '210: What is the risk of Depression in Cluster C disorders?', '["Low", "Very high; social isolation (Avoidant), abusive relationships (Dependent), or burnout (OCPD) often lead to MDD", "None", "None"]', 1, 'Frequent comorbid presentation. (MGH Pocket)'),
    (v_topic_id, '211: Avoidant PD is associated with which attachment style?', '["Secure", "Anxious-Avoidant (or Fearful-Avoidant)", "Disorganized", "None"]', 1, 'Desire intimacy but fear it. (First Aid)'),
    (v_topic_id, '212: Dependent PD is associated with which attachment style?', '["Secure", "Anxious-Preoccupied", "Avoidant", "None"]', 1, 'Clingy and fearful of abandonment. (Kaplan & Sadock)'),
    (v_topic_id, '213: A patient with OCPD is fired from his job. He will likely:', '["Celebrate", "Experience a severe depressive episode, as his self-worth was entirely tied to his productivity and control", "Steal", "None"]', 1, 'Loss of structure is devastating. (MGH Pocket)'),
    (v_topic_id, '214: A patient with Avoidant PD is asked out on a date by someone they really like. They will likely:', '["Say yes immediately", "Find an excuse to say no, convinced the person will eventually discover they are worthless and reject them", "None", "None"]', 1, 'Self-sabotage due to fear. (First Aid)'),
    (v_topic_id, '215: A patient with Dependent PD disagrees with their doctor''s treatment plan. They will likely:', '["Argue", "Say nothing and outwardly comply, but perhaps secretly not take the medication (passive compliance out of fear of angering the doctor)", "None", "None"]', 1, 'They cannot assert themselves. (Kaplan & Sadock)'),
    (v_topic_id, '216: The difference between OCPD and a healthy "Type A" personality?', '["Type A works harder", "OCPD involves significant impairment in functioning or interpersonal distress due to the rigidity. Healthy Type A is productive without the extreme impairment.", "None", "None"]', 1, 'Pathology requires impairment. (MGH Pocket)'),
    (v_topic_id, '217: Avoidant PD vs Social Anxiety Disorder (SAD)?', '["They are completely different", "Highly overlapping; Avoidant PD is often considered a more severe, pervasive, and chronic personality variant of generalized SAD", "None", "None"]', 1, 'SAD can be limited to specific situations (e.g., public speaking). Avoidant PD is pervasive. (First Aid)'),
    (v_topic_id, '218: Dependent PD patients are at increased risk of:', '["Mania", "Domestic violence and exploitation", "Psychosis", "None"]', 1, 'Predators often target them. (Kaplan & Sadock)'),
    (v_topic_id, '219: OCPD patients often struggle to express:', '["Anger", "Warm and tender emotions", "Fear", "None"]', 1, 'They view emotional expression as "messy" and out of control. (MGH Pocket)'),
    (v_topic_id, '220: A patient with Avoidant PD refuses to take a new job because it is in a new city. Why?', '["They hate the city", "Exaggeration of the potential dangers/risks of ordinary situations, using it as an excuse to avoid new people", "None", "None"]', 1, 'They prefer the safe and familiar. (First Aid)'),
    (v_topic_id, '221: A 20-year-old college student calls his mother 5 times a day to ask what he should eat, what to wear, and when to study. Diagnosis?', '["OCPD", "Dependent Personality Disorder", "Autism", "None"]', 1, 'Severe lack of independence. (Kaplan & Sadock)'),
    (v_topic_id, '222: An OCPD surgeon refuses to let the residents close the incision because "they never do the stitches perfectly evenly." This represents:', '["Good teaching", "Reluctance to delegate tasks", "Malpractice", "None"]', 1, 'A classic OCPD trait. (MGH Pocket)'),
    (v_topic_id, '223: Avoidant PD patients often restrict their lifestyle. This means:', '["They eat little", "They have a very narrow routine to ensure they never encounter unexpected social situations", "None", "None"]', 1, 'Their world becomes very small. (First Aid)'),
    (v_topic_id, '224: What happens if you confront a Dependent PD patient too aggressively in therapy?', '["They get angry", "They will likely agree with you immediately to appease you, completely undermining genuine therapeutic progress", "None", "None"]', 1, 'They tell you what you want to hear. (Kaplan & Sadock)'),
    (v_topic_id, '225: OCPD patients use "intellectualization." What does this mean?', '["Being smart", "Dealing with emotional stress by focusing entirely on abstract logic, facts, and rules, completely ignoring the feelings involved", "None", "None"]', 1, 'A defense mechanism. (MGH Pocket)'),
    (v_topic_id, '226: Avoidant PD prevalence in the general population?', '["1%", "2-3%", "10%", "50%"]', 1, 'Relatively common. (First Aid)'),
    (v_topic_id, '227: Dependent PD prevalence?', '["5%", "<1%", "10%", "20%"]', 1, 'Less commonly diagnosed in community samples. (Kaplan & Sadock)'),
    (v_topic_id, '228: OCPD prevalence?', '["1%", "Highly prevalent (up to 2-8%), making it one of the most common personality disorders", "10%", "None"]', 1, 'Very common in high-achieving populations (e.g., medicine, law). (MGH Pocket)'),
    (v_topic_id, '229: An Avoidant PD patient in group therapy:', '["Will dominate the group", "Will likely sit silently, terrified of speaking, unless actively and gently encouraged over many sessions", "Will yell", "None"]', 1, 'Group therapy can be highly effective but is initially terrifying. (First Aid)'),
    (v_topic_id, '230: A Dependent PD patient in group therapy:', '["Will dominate the group", "May attach themselves to a strong member of the group and adopt all of their opinions", "Will leave", "None"]', 1, 'Transference happens with peers too. (Kaplan & Sadock)'),
    (v_topic_id, '231: An OCPD patient in group therapy:', '["Will be silent", "May try to control the group, correct other members, or insist on rigidly following the group rules", "Will cry", "None"]', 1, 'They become the "rule enforcer." (MGH Pocket)'),
    (v_topic_id, '232: Can Avoidant PD be treated with Benzodiazepines?', '["Yes, first line", "No, while they reduce anxiety, they do not treat the core personality pathology and carry high risk of dependence", "None", "None"]', 1, 'CBT is superior. (First Aid)'),
    (v_topic_id, '233: Can Dependent PD be treated with assertiveness training?', '["No", "Yes, it is a core component of CBT for these patients", "None", "None"]', 1, 'Teaching them how to say "no." (Kaplan & Sadock)'),
    (v_topic_id, '234: Do OCPD patients usually seek treatment on their own?', '["Yes", "Rarely. They usually present when a spouse threatens divorce due to their rigidity, or when they develop severe depression/burnout.", "None", "None"]', 1, 'Egosyntonic pathology. (MGH Pocket)'),
    (v_topic_id, '235: The difference between Schizoid and Avoidant? (Review)', '["None", "Schizoid = Aloof (no desire). Avoidant = Afraid (desires but fears).", "None", "None"]', 1, 'Classic board review concept. (First Aid)'),
    (v_topic_id, '236: The difference between OCD and OCPD? (Review)', '["None", "OCD = Egodystonic obsessions/compulsions. OCPD = Egosyntonic perfectionism/control.", "None", "None"]', 1, 'Classic board review concept. (Kaplan & Sadock)'),
    (v_topic_id, '237: A patient with Avoidant PD feels:', '["Inadequate", "Inadequate", "Superior", "None"]', 0, 'Inadequacy is the core feeling. (MGH Pocket)'),
    (v_topic_id, '238: A patient with Dependent PD feels:', '["Independent", "Helpless", "Angry", "None"]', 1, 'Helplessness when alone. (First Aid)'),
    (v_topic_id, '239: A patient with OCPD feels:', '["Relaxed", "A constant need for control and perfection", "Sad", "None"]', 1, 'Control is their safety. (Kaplan & Sadock)'),
    (v_topic_id, '240: Summary statement for OCPD:', '["I am great", "My way or the highway", "I am scared", "None"]', 1, 'Rigidity and control. (MGH Pocket)'),

    -- SECTION 4: Personality Disorder Nuances, Therapy & Defense Mechanisms (241-320)
    (v_topic_id, '241: What is the defining characteristic of an "Egosyntonic" condition?', '["The patient hates it", "The patient perceives their behaviors/thoughts as normal, acceptable, and consistent with their self-image", "None", "None"]', 1, 'This makes Personality Disorders notoriously difficult to treat. (First Aid)'),
    (v_topic_id, '242: What is the defining characteristic of an "Egodystonic" condition?', '["The patient loves it", "The patient recognizes their behaviors/thoughts as intrusive, distressing, and inconsistent with their self-image (e.g., OCD, Panic attacks)", "None", "None"]', 1, 'These patients actively seek help. (Kaplan & Sadock)'),
    (v_topic_id, '243: Which defense mechanism involves reverting to an earlier stage of development under stress?', '["Repression", "Regression (e.g., an adult throwing a temper tantrum or a toilet-trained child wetting the bed when a new sibling is born)", "Denial", "None"]', 1, 'Common in Histrionic and Dependent PDs. (MGH Pocket)'),
    (v_topic_id, '244: Which defense mechanism involves attributing one''s own unacceptable feelings to someone else?', '["Sublimation", "Projection (e.g., a cheating husband accuses his wife of being unfaithful)", "Reaction formation", "None"]', 1, 'Classic for Paranoid Personality Disorder. (First Aid)'),
    (v_topic_id, '245: What is "Reaction Formation"?', '["Running away", "Transforming an unacceptable impulse into its exact opposite (e.g., a man who harbors secret homosexual desires becomes a violently homophobic preacher)", "None", "None"]', 1, 'Overcompensation. (Kaplan & Sadock)'),
    (v_topic_id, '246: What is "Splitting"?', '["Breaking things", "Categorizing people or situations as entirely good or entirely bad, unable to integrate positive and negative qualities", "None", "None"]', 1, 'Hallmark of Borderline Personality Disorder. (MGH Pocket)'),
    (v_topic_id, '247: What is "Acting Out"?', '["Being in a play", "Expressing unacceptable feelings or conflicts through actions rather than words (e.g., punching a wall instead of saying ''''I''m angry'''')", "None", "None"]', 1, 'Common in Antisocial and Borderline PDs. (First Aid)'),
    (v_topic_id, '248: What is "Intellectualization"?', '["Being smart", "Using facts and logic to distance oneself from a stressful or emotional situation (e.g., a doctor diagnosed with cancer obsessively researches the molecular biology of the tumor rather than grieving)", "None", "None"]', 1, 'Classic for OCPD. (Kaplan & Sadock)'),
    (v_topic_id, '249: What is "Isolation of Affect"?', '["Being alone", "Separating an idea from its associated emotional state (e.g., describing a horrific trauma with a blank, emotionless expression)", "None", "None"]', 1, 'Common in PTSD and Schizoid PD. (MGH Pocket)'),
    (v_topic_id, '250: What is "Rationalization"?', '["Doing math", "Creating logical or acceptable excuses for unacceptable behavior or feelings (e.g., ''''I didn''t get the job because the interviewer was biased,'''' not because I was unqualified)", "None", "None"]', 1, 'A ubiquitous defense mechanism. (First Aid)'),
    (v_topic_id, '251: What is "Displacement"?', '["Moving away", "Redirecting an emotion or impulse from its original, dangerous target to a safer target (e.g., angry at your boss, so you go home and kick the dog)", "None", "None"]', 1, 'Transferring anger down the hierarchy. (Kaplan & Sadock)'),
    (v_topic_id, '252: What is "Denial"?', '["Lying", "Refusing to acknowledge an obvious, painful reality (e.g., a patient with a massive heart attack insists it''s just indigestion and goes for a jog)", "None", "None"]', 1, 'A primitive defense mechanism. (MGH Pocket)'),
    (v_topic_id, '253: Which of the following are considered MATURE defense mechanisms?', '["Projection, Splitting", "Sublimation, Humor, Altruism, Suppression", "Denial, Regression", "None"]', 1, 'Mature defenses are healthy and adaptive. (First Aid)'),
    (v_topic_id, '254: What is "Sublimation"?', '["Freezing", "Channeling an unacceptable impulse into a socially acceptable or productive activity (e.g., a person with aggressive urges becomes a professional boxer or a surgeon)", "None", "None"]', 1, 'The most mature defense mechanism. (Kaplan & Sadock)'),
    (v_topic_id, '255: What is "Suppression"?', '["Forgetting", "CONSCIOUSLY deciding to push an unwanted thought or feeling out of awareness (e.g., ''''I''m not going to think about the exam right now so I can enjoy this movie'''')", "None", "None"]', 1, 'Mature, because it is conscious. (MGH Pocket)'),
    (v_topic_id, '256: How does Suppression differ from Repression?', '["They are the same", "Suppression is CONSCIOUS. Repression is UNCONSCIOUS (the memory is completely blocked from awareness without the person trying).", "None", "None"]', 1, 'Crucial distinction. (First Aid)'),
    (v_topic_id, '257: What is "Altruism" as a defense mechanism?', '["Giving money", "Alleviating negative feelings (like guilt) by helping others in a genuine, self-sacrificing way", "None", "None"]', 1, 'A mature defense. (Kaplan & Sadock)'),
    (v_topic_id, '258: What is "Humor" as a defense mechanism?', '["Telling jokes", "Appreciating the amusing nature of an anxiety-provoking situation to relieve stress", "None", "None"]', 1, 'A mature defense. (MGH Pocket)'),
    (v_topic_id, '259: "Projective Identification" is a complex defense where:', '["You forget your name", "The patient projects a feeling onto the therapist, and the therapist actually internalizes and experiences that feeling", "None", "None"]', 1, 'Often seen in severe Borderline PD. (First Aid)'),
    (v_topic_id, '260: Transference is:', '["Moving hospitals", "The PATIENT unconsciously projecting feelings about an important figure from their past (e.g., a parent) onto the PHYSICIAN", "None", "None"]', 1, 'E.g., rebelling against the doctor as if the doctor were their strict father. (Kaplan & Sadock)'),
    (v_topic_id, '261: Countertransference is:', '["Reverse moving", "The PHYSICIAN unconsciously projecting their own feelings/past experiences onto the PATIENT", "None", "None"]', 1, 'E.g., feeling unusually protective of a young patient who resembles the doctor''s child. (MGH Pocket)'),
    (v_topic_id, '262: Is countertransference always bad?', '["Yes", "No, it is a normal human reaction. The key is for the physician to RECOGNIZE it and not let it dictate clinical care.", "None", "None"]', 1, 'Self-awareness is essential in psychiatry. (First Aid)'),
    (v_topic_id, '263: What is "Splitting" among hospital staff?', '["Firing staff", "When a Borderline patient manipulates staff into taking sides against each other (e.g., day shift vs night shift), causing severe team conflict", "None", "None"]', 1, 'Requires unified team meetings to resolve. (Kaplan & Sadock)'),
    (v_topic_id, '264: A physician feels intensely angry every time a particular Narcissistic patient comes to the clinic. This is an example of:', '["Transference", "Countertransference", "Projection", "None"]', 1, 'The doctor''s emotional reaction. (MGH Pocket)'),
    (v_topic_id, '265: A patient idealizes their new therapist, saying "You are the only person who has ever understood me, my last therapist was an idiot." What defense mechanism is this?', '["Sublimation", "Splitting (Idealization/Devaluation)", "Denial", "None"]', 1, 'The therapist will soon be devalued as well. (First Aid)'),
    (v_topic_id, '266: What is the best therapeutic approach when a patient is splitting the treatment team?', '["Agree with the patient", "Maintain clear, consistent boundaries, ensure all team members communicate, and present a unified front to the patient", "Yell at the patient", "None"]', 1, 'Consistency is the antidote to splitting. (Kaplan & Sadock)'),
    (v_topic_id, '267: Psychoanalytic Psychotherapy focuses on:', '["Medication", "Uncovering unconscious conflicts, early childhood experiences, and utilizing transference to gain insight", "Breathing", "None"]', 1, 'Based on Freud''s theories. (MGH Pocket)'),
    (v_topic_id, '268: Cognitive Behavioral Therapy (CBT) focuses on:', '["The unconscious", "Identifying and modifying distorted, maladaptive thoughts (cognitive distortions) to change behaviors and emotions in the HERE AND NOW", "Childhood", "None"]', 1, 'The most widely evidence-based therapy. (First Aid)'),
    (v_topic_id, '269: Dialectical Behavior Therapy (DBT) is specifically designed for:', '["Schizophrenia", "Borderline Personality Disorder (focuses on emotional regulation, distress tolerance, and mindfulness)", "ADHD", "None"]', 1, 'Reduces self-harm and suicide. (Kaplan & Sadock)'),
    (v_topic_id, '270: Supportive Psychotherapy focuses on:', '["Deep analysis", "Bolstering the patient''s current defenses, building self-esteem, and providing a safe, empathetic environment without deeply probing unconscious conflicts", "None", "None"]', 1, 'Used in crisis or for very fragile patients (e.g., severe Cluster A). (MGH Pocket)'),
    (v_topic_id, '271: Group Therapy is highly effective for which condition?', '["Acute Psychosis", "Substance Use Disorders and some Personality Disorders (e.g., Avoidant PD), providing peer feedback and reducing isolation", "None", "None"]', 1, 'Allows patients to practice interpersonal skills. (First Aid)'),
    (v_topic_id, '272: Family Therapy conceptualizes the "patient" as:', '["The child", "The entire family system; the identified patient''s symptoms are seen as a manifestation of family dysfunction", "The mother", "None"]', 1, 'Treats the system, not just the individual. (Kaplan & Sadock)'),
    (v_topic_id, '273: In CBT, what is "Catastrophizing"?', '["A natural disaster", "A cognitive distortion where the patient assumes the worst possible outcome will happen (e.g., ''''If I fail this test, my life is completely over'''')", "None", "None"]', 1, 'CBT challenges these thoughts. (MGH Pocket)'),
    (v_topic_id, '274: In CBT, what is "Black-and-White Thinking" (All-or-Nothing thinking)?', '["Color blindness", "Seeing things in absolute terms (''''If I''m not perfect, I''m a total failure''''); very common in OCPD and Eating Disorders", "None", "None"]', 1, 'Similar to splitting but a cognitive distortion. (First Aid)'),
    (v_topic_id, '275: "Mindfulness" in DBT involves:', '["Sleeping", "Focusing completely on the present moment, observing thoughts/feelings without judging them or acting on them", "None", "None"]', 1, 'Rooted in Zen Buddhism. (Kaplan & Sadock)'),
    (v_topic_id, '276: What is a "Factitious Disorder" (Munchausen Syndrome)?', '["Faking for money", "INTENTIONALLY producing or feigning physical/psychological symptoms to assume the ''''sick role'''' and gain medical attention (internal primary gain)", "None", "None"]', 1, 'There is NO external reward (like money or drugs). (MGH Pocket)'),
    (v_topic_id, '277: How does Factitious Disorder differ from Malingering?', '["They are the same", "Malingering involves faking symptoms for a tangible EXTERNAL reward (e.g., money, avoiding jail, getting opioids). Factitious disorder seeks the SICK ROLE (internal gain).", "None", "None"]', 1, 'Malingering is not a psychiatric illness; it is fraud. (First Aid)'),
    (v_topic_id, '278: How does Factitious Disorder differ from Somatic Symptom Disorder?', '["Same", "In Somatic Symptom Disorder, the patient is NOT intentionally faking; they genuinely believe they are sick. Factitious patients INTENTIONALLY deceive.", "None", "None"]', 1, 'Intentionality is the key differentiator. (Kaplan & Sadock)'),
    (v_topic_id, '279: Factitious Disorder Imposed on Another (Munchausen by Proxy)?', '["Faking illness", "Intentionally producing illness in another person (usually a child) to gain attention/sympathy for oneself; a form of severe CHILD ABUSE", "None", "None"]', 1, 'Must report to Child Protective Services immediately. (MGH Pocket)'),
    (v_topic_id, '280: A patient injects insulin to induce hypoglycemia, presenting to the ER with seizures. When told they will be admitted, they seem pleased. Diagnosis?', '["Malingering", "Factitious Disorder", "Conversion Disorder", "None"]', 1, 'Intentional harm for medical attention. (First Aid)'),
    (v_topic_id, '281: A patient claims severe back pain to get a disability check. Diagnosis?', '["Factitious Disorder", "Malingering", "Somatic Symptom Disorder", "None"]', 1, 'External secondary gain (money). (Kaplan & Sadock)'),
    (v_topic_id, '282: A classic clue for Factitious Disorder?', '["Never goes to doctor", "Patient has a massive medical file, multiple unexplained abdominal surgeries (gridiron abdomen), and works in the healthcare field", "None", "None"]', 1, 'They know the medical jargon. (MGH Pocket)'),
    (v_topic_id, '283: What is "Conversion Disorder" (Functional Neurological Symptom Disorder)?', '["Faking", "UNCONSCIOUS neurological symptoms (e.g., blindness, paralysis, seizures) that cannot be explained medically, often triggered by acute psychological stress", "None", "None"]', 1, 'The psychological distress "converts" into a physical deficit. (First Aid)'),
    (v_topic_id, '284: What is "La Belle Indifférence" in Conversion Disorder?', '["A perfume", "A paradoxical lack of concern about their severe neurological symptom (e.g., ''''Oh well, I guess my legs don''t work today'''')", "None", "None"]', 1, 'Classic, though not always present. (Kaplan & Sadock)'),
    (v_topic_id, '285: A 20-year-old woman suddenly goes blind after witnessing a horrific car accident. Neuro exam, including pupillary reflexes and EEG, is completely normal. Diagnosis?', '["Malingering", "Conversion Disorder", "Factitious Disorder", "None"]', 1, 'Unconscious symptom tied to a stressor. (MGH Pocket)'),
    (v_topic_id, '286: Are Personality Disorders typically diagnosed in the ER?', '["Always", "Rarely. The ER is for acute stabilization; PDs require long-term observation to establish a ''''pervasive and enduring'''' pattern", "None", "None"]', 1, 'Avoid slapping a PD label on a patient in crisis. (First Aid)'),
    (v_topic_id, '287: Which personality disorder is most likely to repeatedly sue their doctor?', '["Avoidant", "Paranoid Personality Disorder", "Dependent", "None"]', 1, 'Due to pervasive distrust and litigiousness. (Kaplan & Sadock)'),
    (v_topic_id, '288: Which personality disorder is most likely to demand a different doctor because the current one isn''t "prestigious enough"?', '["Borderline", "Narcissistic Personality Disorder", "Schizoid", "None"]', 1, 'Grandiosity and entitlement. (MGH Pocket)'),
    (v_topic_id, '289: Which personality disorder is most likely to seduce their doctor?', '["Schizotypal", "Histrionic Personality Disorder", "Avoidant", "None"]', 1, 'Inappropriate sexual seductiveness. (First Aid)'),
    (v_topic_id, '290: Which personality disorder is most likely to threaten to kill themselves in the waiting room if the doctor doesn''t see them right now?', '["Antisocial", "Borderline Personality Disorder", "OCPD", "None"]', 1, 'Frantic efforts to avoid abandonment / impulsivity. (Kaplan & Sadock)'),
    (v_topic_id, '291: Which personality disorder is most likely to steal prescription pads from the doctor''s office?', '["Avoidant", "Antisocial Personality Disorder", "Dependent", "None"]', 1, 'Deceitfulness and violation of rules/laws. (MGH Pocket)'),
    (v_topic_id, '292: Which personality disorder is most likely to refuse a life-saving surgery because "the hospital is part of a government conspiracy"?', '["Dependent", "Paranoid Personality Disorder or Schizotypal PD", "OCPD", "None"]', 1, 'Extreme paranoia. (First Aid)'),
    (v_topic_id, '293: Which personality disorder is most likely to miss their appointment because they were too afraid the receptionist would judge their outfit?', '["Antisocial", "Avoidant Personality Disorder", "Schizoid", "None"]', 1, 'Hypersensitivity to negative evaluation. (Kaplan & Sadock)'),
    (v_topic_id, '294: Which personality disorder is most likely to bring their mother into the exam room and ask her to answer all the doctor''s questions?', '["Narcissistic", "Dependent Personality Disorder", "Histrionic", "None"]', 1, 'Inability to make decisions or function independently. (MGH Pocket)'),
    (v_topic_id, '295: Which personality disorder is most likely to bring a 10-page, color-coded spreadsheet of their daily blood pressure readings taken every 15 minutes?', '["Borderline", "Obsessive-Compulsive Personality Disorder (OCPD)", "Antisocial", "None"]', 1, 'Preoccupation with details, lists, and order. (First Aid)'),
    (v_topic_id, '296: Which personality disorder is most likely to ignore the doctor completely, staring blankly at the wall, with no desire to engage in conversation?', '["Histrionic", "Schizoid Personality Disorder", "Dependent", "None"]', 1, 'Detachment and flat affect. (Kaplan & Sadock)'),
    (v_topic_id, '297: A patient with Borderline PD improves significantly when:', '["Given opioids", "They form a stable, long-term, non-abusive relationship (e.g., with a therapist or supportive partner) that survives their ''''testing'''' behavior", "None", "None"]', 1, 'Stability heals the attachment trauma. (MGH Pocket)'),
    (v_topic_id, '298: The cornerstone of managing ANY personality disorder in the medical setting is:', '["Giving them whatever they want", "Establishing firm, consistent, and objective boundaries, and maintaining a non-judgmental professional stance", "Kicking them out", "None"]', 1, 'Boundaries protect both the patient and the physician. (First Aid)'),
    (v_topic_id, '299: Can personality disorders change?', '["Never", "Yes. While enduring, traits can soften over time, especially with intensive psychotherapy and aging (e.g., ASPD and BPD tend to improve in middle age).", "None", "None"]', 1, 'They are not a life sentence. (Kaplan & Sadock)'),
    (v_topic_id, '300: Personality Disorder vs Mood Disorder?', '["Same", "Personality Disorders are chronic, pervasive, and egosyntonic. Mood disorders are episodic, state-dependent, and egodystonic.", "None", "None"]', 1, 'The core differential diagnostic principle. (MGH Pocket)'),
    (v_topic_id, '301: A patient says, "I didn''t steal the car, I just borrowed it indefinitely without asking." This is:', '["Denial", "Rationalization", "Sublimation", "None"]', 1, 'Creating an acceptable excuse. (First Aid)'),
    (v_topic_id, '302: A patient says, "My boss is the one who is angry, not me!" while slamming his fist on the desk. This is:', '["Projection", "Projection", "Displacement", "None"]', 0, 'Attributing his own anger to the boss. (Kaplan & Sadock)'),
    (v_topic_id, '303: A child who is abused grows up to become a passionate advocate for child protective services. This is:', '["Reaction Formation", "Sublimation", "Repression", "None"]', 1, 'Channeling trauma into a productive, socially beneficial outcome. (MGH Pocket)'),
    (v_topic_id, '304: A patient with terminal cancer talks enthusiastically about his plans to run a marathon next year. This is:', '["Denial", "Denial", "Intellectualization", "None"]', 0, 'Refusing to accept the reality of the prognosis. (First Aid)'),
    (v_topic_id, '305: A woman who is secretly resentful of her mother becomes overly devoted, calling her 10 times a day to make sure she is okay. This is:', '["Sublimation", "Reaction Formation", "Acting Out", "None"]', 1, 'Doing the exact opposite of her unacceptable impulse (resentment). (Kaplan & Sadock)'),
    (v_topic_id, '306: A man gets yelled at by his wife, so he goes outside and kicks the trash can. This is:', '["Projection", "Displacement", "Sublimation", "None"]', 1, 'Moving the anger to a safer target. (MGH Pocket)'),
    (v_topic_id, '307: An adult patient in the hospital insists on keeping a teddy bear in the bed and speaks in a baby voice when scared. This is:', '["Repression", "Regression", "Denial", "None"]', 1, 'Reverting to a childlike state under stress. (First Aid)'),
    (v_topic_id, '308: A medical student refuses to think about the looming USMLE Step 1 exam so they can enjoy their brother''s wedding. This is:', '["Repression", "Suppression (conscious)", "Denial", "None"]', 1, 'A mature, conscious decision. (Kaplan & Sadock)'),
    (v_topic_id, '309: A woman who was severely abused as a child has absolutely no memory of the abuse until she is 40. This is:', '["Suppression", "Repression (unconscious)", "Denial", "None"]', 1, 'The memory was unconsciously blocked. (MGH Pocket)'),
    (v_topic_id, '310: A patient says, "The day nurse is a genius, but the night nurse is actively trying to kill me." This is:', '["Splitting", "Splitting", "Projection", "None"]', 0, 'All good vs all bad. (First Aid)'),
    (v_topic_id, '311: Treating a patient with Factitious Disorder?', '["Confront them aggressively", "Avoid direct, angry confrontation which will cause them to flee. Use a non-punitive, supportive approach to address the underlying psychological need.", "Call the police", "None"]', 1, 'They are truly suffering from a psychiatric illness. (Kaplan & Sadock)'),
    (v_topic_id, '312: Treating a patient who is Malingering?', '["Give them what they want", "Document objective findings, gently confront with evidence, and firmly refuse unwarranted treatments/disability forms. Do not prescribe opioids.", "None", "None"]', 1, 'Maintain strict clinical integrity. (MGH Pocket)'),
    (v_topic_id, '313: Treating Conversion Disorder?', '["Tell them it''s in their head", "Reassurance, physical therapy, and psychotherapy. Symptoms usually resolve spontaneously. Avoid unnecessary invasive tests.", "Surgery", "None"]', 1, 'Do not reinforce the symptom, but validate the distress. (First Aid)'),
    (v_topic_id, '314: Is Psychopathy in the DSM-5?', '["Yes", "No, it is a clinical construct often assessed using the Hare Psychopathy Checklist (PCL-R), falling under the umbrella of severe ASPD", "None", "None"]', 1, 'Forensic psychiatry concept. (Kaplan & Sadock)'),
    (v_topic_id, '315: The "Dark Triad" of personality?', '["Sad, mad, bad", "Narcissism, Machiavellianism (manipulativeness), and Psychopathy", "None", "None"]', 1, 'Traits associated with malevolent interpersonal behavior. (MGH Pocket)'),
    (v_topic_id, '316: A physician starts crying during a session because the patient reminds him of his deceased brother. What should the physician do?', '["Keep treating", "Seek supervision or personal therapy, and consider transferring the patient if the countertransference severely impairs objectivity", "None", "None"]', 1, 'Professional boundaries must be maintained. (First Aid)'),
    (v_topic_id, '317: A Borderline patient brings a gift for the therapist. Should the therapist accept?', '["Always", "Usually no. Gifts in therapy complicate the boundary and transference. It must be explored therapeutically why the gift was offered.", "None", "None"]', 1, 'Boundaries are the foundation of BPD treatment. (Kaplan & Sadock)'),
    (v_topic_id, '318: The overarching goal of treating Personality Disorders?', '["Cure them", "Reduce impairment, improve interpersonal functioning, and increase the patient''s awareness of their maladaptive patterns", "None", "None"]', 1, 'Management, not cure. (MGH Pocket)'),
    (v_topic_id, '319: What is the most important trait for a psychiatrist treating severe Personality Disorders?', '["High IQ", "Patience, strong boundaries, and the ability to tolerate extreme emotional states without reacting personally", "None", "None"]', 1, 'It is demanding but rewarding work. (First Aid)'),
    (v_topic_id, '320: Final Pearl: Personality is defined as:', '["Temporary mood", "The enduring, deeply ingrained patterns of perceiving, relating to, and thinking about the environment and oneself", "None", "None"]', 1, 'It is the lens through which we view the world. (MediHelp Mastery)');
END $$;

COMMIT;
